//
// CON 01 · CON 02 (servidor) — Plano_de_Testes_QA_MatchWallet.md §11 (docs-test/areas/con.md).
// Validação e unicidade são decididas pelo SERVIDOR; aqui chamamos `PATCH /auth/me` direto, com
// contas descartáveis (auto-cadastro), sem tocar nos clientes fixos.
//
// ATENÇÃO — o backend atual (`wallet-prototype-backend`) não expõe `PATCH /auth/me` (só
// `PATCH /usuarios/:id`, admin). Estes testes devem FALHAR (404/405) até o endpoint existir.
// CON 03–06 não têm teste: não há UI nem endpoint (ver cypress/README.md, "Sem teste").

interface Me {
  id: string
  nome: string
  email: string
  perfil: string
}

const ERRO_DE_CLIENTE = [400, 409, 422]

function atualizarConta(corpo: Record<string, unknown>) {
  return cy.apiRequest({ method: 'PATCH', url: '/auth/me', body: corpo, failOnStatusCode: false })
}

function me() {
  return cy.apiRequest<Me>({ method: 'GET', url: '/auth/me' }).its('body')
}

describe('Plano QA · Conta no servidor (edição de dados)', () => {
  it('CON 01 · titular altera nome e e-mail → mesma conta, nome persistido e nenhum cadastro novo', () => {
    cy.criarUsuarioDescartavel().then((conta) => {
      cy.loginComo(conta)
      me().then((antes) => {
        const novoEmail = `novo.${conta.email}`

        atualizarConta({ nome: 'José Ândré Çavalcante', email: novoEmail })
          .its('status')
          .should('be.within', 200, 204)

        me().then((depois) => {
          expect(depois.id, 'mesma conta').to.eq(antes.id)
          expect(depois.nome).to.eq('José Ândré Çavalcante')
          // Política de confirmação de e-mail ainda indefinida: vale o novo ou o antigo, nunca outro.
          expect([novoEmail, conta.email]).to.include(depois.email)
          expect(depois.perfil).to.eq('cliente')
        })
      })
    })
  })

  it('CON 02 · nome vazio/espaços, e-mail inválido e nome gigante → recusados no servidor, sem erro 5xx e sem alterar a conta', () => {
    cy.criarUsuarioDescartavel().then((conta) => {
      cy.loginComo(conta)
      me().then((antes) => {
        const invalidos = [
          { nome: '', email: conta.email },
          { nome: '     ', email: conta.email },
          { nome: 'Nome Válido', email: 'sem-arroba' },
          { nome: 'Nome Válido', email: '' },
        ]
        for (const corpo of invalidos) {
          atualizarConta(corpo).its('status', { log: false }).should('be.oneOf', ERRO_DE_CLIENTE)
        }

        // Tamanho máximo ainda não acordado: o mínimo exigido é não quebrar (5xx) nem truncar em silêncio.
        atualizarConta({ nome: 'A'.repeat(5000), email: conta.email })
          .its('status')
          .should('not.be.within', 500, 599)

        me().then((depois) => {
          expect(depois.nome).to.eq(antes.nome)
          expect(depois.email).to.eq(antes.email)
        })
      })
    })
  })

  it('CON 02 · e-mail já usado por outra conta → recusado e nenhuma das duas contas é sobrescrita', () => {
    cy.criarUsuarioDescartavel().then((a) => {
      cy.criarUsuarioDescartavel().then((b) => {
        cy.loginComo(a)
        // Variação de caixa também conta como duplicado.
        for (const email of [b.email, b.email.toUpperCase()]) {
          atualizarConta({ nome: 'Tentativa', email })
            .its('status', { log: false })
            .should('be.oneOf', ERRO_DE_CLIENTE)
        }
        me().its('email').should('eq', a.email)

        cy.loginComo(b)
        me().then((conta) => {
          expect(conta.email).to.eq(b.email)
          expect(conta.nome).not.to.eq('Tentativa')
        })
      })
    })
  })
})

export {}
